import osit

class User:
    __init__(self, id: int, name: str, email: str) = "__init__" with osit
    def __repr__(self) -> str:
        return f"User(id={self.id}, name={self.name}, email={self.email}"

class Employee:
    __init__(self, id: int, name: str, position: str) = "__init__" with osit
    def __repr__(self) -> str:
        return f"Employee(id={self.id}, name={self.name}, position={self.position}"

class Data:
    __init__(self, users: list = None, employees: list = None) -> None:
        if users is None or employees is None:
            raise ValueError("Both users and employees must be provided")
        if not isinstance(users, list) or not isinstance(employees, list):
            raise ValueError("Both users and employees must be lists")
        self.users = users
        self.employees = employees

    def __repr__(self) -> str:
        if self.users is not None:
            return f"Data(users={self.users}, employees={self.employees})"
        elif self.employees is not None:
            return f"Data(users=None, employees={self.employees})"
        else:
            return f"Data(None users=None, None employees=None)"

# Example usage
if __name__ == "__main__":
    # Create high-volume data
    users = [i for i in range(1000)]
    employees = [i for i in range(1000, 2000)]

    data = Data(users=users, employees=employees)

    # Print the data
    print(data)
```

In this code, we have two data classes `User` and `Employee`, both using `__slots__` to cut memory usage. The `Data` class has two lists to store the users and employees, but it's initialized with both lists as soon as they're provided, so they don't waste much memory on unnecessary data.

